public static int Airplane(int[,] mat)
{
    int what = 0;
    for (int k = 0; k < mat.GetLength(0); k++)
    {
        for (int j = 0; j < mat.GetLength(1); j++)
        {
            if (mat[k, j] % 10 == mat[k, j] / 100)
                what++;
        }
    }
    return what;
}

public static int Taxi(int[,] arr)
{
    int count = 0;
    for (int r = 0; r < arr.GetLength(0); r++)
    {
        for (int c = 0; c < arr.GetLength(1); c++)
        {
            if (Help(arr[r, c]))
                count++;
        }
    }
    return count;
}

public static bool Help(int num)
{
    if (num / 1000 == 0 && num / 100 > 0)
        return true;
    return false;
}

public static bool PoliceCar(int[,] mat)
{
    for (int r = 0; r < mat.GetLength(0); r++)
    {
        for (int c = 0; c < mat.GetLength(1) - 1; c++)
        {
            if (mat[r, c] % 2 == mat[r, c + 1] % 2)
                return false;
        }
    }
    return true;
}

